#!/bin/bash
# Only repack rootfs.tar.gz from rootfs-duo-42 (boot image v3 stays untouched – the flash-safely confirmation applies per image!).
# Compared with 5-stufen-bauen.sh: /usr/lib/firmware stays IN (modem/WLAN/GPU firmware, 92 MB), build leftovers under /root stay out.
set -e; R=/home/user/duo-a1/rootfs-duo-42; cd /home/user/duo-a1
[ -f out/rootfs.tar.gz ] && cp -f out/rootfs.tar.gz out/rootfs.tar.gz.vorher
tar -C "$R" --exclude=./usr/share/doc --exclude=./usr/share/man --exclude=./usr/share/info --exclude='./usr/share/locale/[!d]*' --exclude='./usr/share/locale/d[!e]*' --exclude=./usr/share/licenses --exclude=./var/cache/dnf --exclude=./var/cache/libdnf5 --exclude='./usr/lib64/firefox/langpacks/langpack-[!d]*' --exclude=./usr/share/speech-dispatcher --exclude=./usr/share/sgml --exclude=./usr/lib/gcc --exclude=./var/cache --exclude=./var/lib/dnf --exclude=./var/lib/rpm --exclude=./usr/lib/.build-id --exclude=./usr/share/hwdata --exclude=./usr/share/cracklib --exclude='./usr/lib64/python3*/__pycache__' --exclude=./proc --exclude=./sys --exclude=./dev --exclude=./run --exclude=./tmp --exclude=./root/rpmbuild --exclude=./root/src-qcom --exclude=./root/nm --exclude=./root/niri-canvas --exclude=./root/matrixkit --exclude=./root/matrixkit-cargo --exclude=./root/matugen-bau --exclude='./root/*.rpm' --exclude=./root/.cache --exclude=./usr/include --exclude=./usr/share/gtk-doc --exclude=./usr/share/gir-1.0 --exclude=./usr/lib64/pkgconfig --exclude=./usr/lib64/cmake --exclude=./usr/share/vala --exclude='./usr/lib64/*.a' --exclude=./usr/lib/rustlib --exclude='./usr/lib64/librustc_driver*' --exclude=./usr/bin/cargo --exclude=./usr/bin/rustc --exclude=./usr/bin/rustdoc --exclude='./usr/lib64/libclang*' --exclude='./usr/bin/clang*' --exclude=./usr/bin/c-index-test --exclude='./usr/bin/llvm-*' --exclude=./usr/bin/lto-dump --exclude=./usr/libexec/gcc --exclude=./usr/lib64/clc --exclude=./usr/lib64/d3d --exclude='./usr/lib64/libRusticlOpenCL*' --exclude='./usr/bin/lld*' --exclude=./usr/bin/ld.lld -czf out/rootfs.tar.gz .
chown "${SUDO_USER:-root}": out/rootfs.tar.gz; ls -la out/rootfs.tar.gz | awk '{print $5, $9}'
tar -tzf out/rootfs.tar.gz | grep -cE "^./usr/lib/firmware/(modem.mdt|wlanmdsp.mbn|wlan/qca_cld/WCNSS_qcom_cfg.ini)$|^./(usr/)?lib/modules/.*/wlan.ko$|^./etc/systemd/system/duo-wlan.service$" | sed 's/^/Kontrolle (erwartet 5): /'
